-- =====================================================================
-- LAG & LEAD : LARGE REAL-WORLD DATASET
-- Requirement: MySQL 8.0+
-- Database: lag_lead_real   (separate from the small practice database)
--
-- Tables (all data is realistic but generated for practice):
--   0) shop_sales          7 rows : one week of sales of a small shop (for LEVEL 1)
--   1) stock_daily      600 rows : NSE-style daily prices of 5 companies, Jan-Jun 2024
--   2) customers         120 rows : e-commerce customers
--   3) orders            694 rows : e-commerce orders in 2024
--   4) monthly_sales      96 rows : revenue of 4 regions for 24 months (2023-2024)
--   5) salary_history    166 rows : salary revisions of 30 employees
--   6) app_daily_users   174 rows : daily active users of an app (some dates missing)
--
-- Run this whole file once, then open 05_large_practice_questions.sql
-- =====================================================================

CREATE DATABASE IF NOT EXISTS lag_lead_real;
USE lag_lead_real;

DROP TABLE IF EXISTS shop_sales;
DROP TABLE IF EXISTS stock_daily;
DROP TABLE IF EXISTS orders;
DROP TABLE IF EXISTS customers;
DROP TABLE IF EXISTS monthly_sales;
DROP TABLE IF EXISTS salary_history;
DROP TABLE IF EXISTS app_daily_users;

-- ---------------------------------------------------------------------
-- 0) shop_sales : ONE week of sales of a small tea shop (only 7 rows)
--    Small on purpose -> you can SEE how LAG / LEAD move values up and down.
-- ---------------------------------------------------------------------
CREATE TABLE shop_sales (
    sale_date DATE,
    day_name  VARCHAR(10),
    sales     INT
);


-- ---------------------------------------------------------------------
-- 1) stock_daily : one row per stock per trading day (no weekends / holidays)
-- ---------------------------------------------------------------------
CREATE TABLE stock_daily (
    symbol       VARCHAR(15),
    company_name VARCHAR(60),
    sector       VARCHAR(30),
    trade_date   DATE,
    open_price   DECIMAL(10,2),
    high_price   DECIMAL(10,2),
    low_price    DECIMAL(10,2),
    close_price  DECIMAL(10,2),
    volume       BIGINT
);



-- ---------------------------------------------------------------------
-- 2) customers
-- ---------------------------------------------------------------------
CREATE TABLE customers (
    customer_id   INT PRIMARY KEY,
    customer_name VARCHAR(60),
    city          VARCHAR(30),
    signup_date   DATE
);


-- ---------------------------------------------------------------------
-- 3) orders : e-commerce orders placed in 2024
-- ---------------------------------------------------------------------
CREATE TABLE orders (
    order_id     INT PRIMARY KEY,
    customer_id  INT,
    order_date   DATE,
    category     VARCHAR(30),
    amount       DECIMAL(10,2),
    payment_mode VARCHAR(20),
    order_status VARCHAR(20)
);


-- ---------------------------------------------------------------------
-- 4) monthly_sales : one row per region per month (Jan-2023 to Dec-2024)
-- ---------------------------------------------------------------------
CREATE TABLE monthly_sales (
    region      VARCHAR(10),
    sales_month DATE,          -- always the 1st day of the month
    revenue     DECIMAL(12,2),
    units_sold  INT,
    marketing_spend DECIMAL(12,2)
);


-- ---------------------------------------------------------------------
-- 5) salary_history : every salary revision (first row = joining salary)
-- ---------------------------------------------------------------------
CREATE TABLE salary_history (
    emp_id       INT,
    emp_name     VARCHAR(60),
    department   VARCHAR(30),
    designation  VARCHAR(40),
    effective_date DATE,
    annual_salary  INT
);


-- ---------------------------------------------------------------------
-- 6) app_daily_users : daily active users of a mobile app (Jan-Jun 2024)
--    NOTE: tracking failed on some days, so those dates are MISSING.
-- ---------------------------------------------------------------------
CREATE TABLE app_daily_users (
    activity_date DATE,
    active_users  INT,
    new_signups   INT,
    sessions      INT
);

